mapper.update:
CREATE TABLE IF NOT EXISTS TB_EEP_LAB_RESEARCHER_M ( RSCH_SQ int NOT NULL AUTO_INCREMENT , STAFF_SQ int NOT NULL , ROLE_CD varchar(10) NOT NULL COMMENT 'HEAD 연구소장, MEMBER 연구원' , START_DT date NOT NULL COMMENT '소속 시작일' , END_DT date NULL COMMENT '소속 종료일' , UPDT_EMPLY_ID varchar(50) NULL , UPDT_DT datetime NULL , PRIMARY KEY (RSCH_SQ) , KEY IX_LAB_RSCH_STAFF (STAFF_SQ) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='연구소 연구원 소속 기간';
CREATE TABLE IF NOT EXISTS TB_EEP_LAB_PROJECT_M ( PRJ_SQ int NOT NULL AUTO_INCREMENT , PRJ_NM varchar(200) NOT NULL , START_DT date NOT NULL , END_DT date NOT NULL , PLACE varchar(200) NOT NULL , MANAGER_EMPLY_ID varchar(50) NULL COMMENT '안 씀: 결재라인은 TB_EEP_LAB_APPR_R' , CEO_EMPLY_ID varchar(50) NULL COMMENT '안 씀: 결재라인은 TB_EEP_LAB_APPR_R' , DRIVE_FOLDER_ID varchar(100) NOT NULL COMMENT '드라이브 과제 폴더 ID' , UPDT_EMPLY_ID varchar(50) NULL , UPDT_DT datetime NULL , PRIMARY KEY (PRJ_SQ) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='연구과제';
CREATE TABLE IF NOT EXISTS TB_EEP_LAB_JOURNAL_M ( JRN_SQ int NOT NULL AUTO_INCREMENT , PRJ_SQ int NOT NULL , YM char(7) NOT NULL COMMENT '대상 월 yyyy-MM' , CONTENT mediumtext NULL , STATUS_CD varchar(12) NOT NULL COMMENT 'DRAFT, SUBMITTED, APPROVED, CLOSED' , WRITER_EMPLY_ID varchar(50) NOT NULL , WRITER_NM varchar(100) NULL , SNAP_PRJ_NM varchar(200) NULL COMMENT '제출 시점 과제명 (이후 과제를 고쳐도 일지는 그대로)' , SNAP_PLACE varchar(200) NULL , SNAP_PERIOD varchar(30) NULL , SNAP_MEMBERS varchar(2000) NULL COMMENT '제출 시점 연구인원' , PDF_FILE_ID varchar(100) NULL , PDF_LINK varchar(500) NULL , UPLOAD_ERR varchar(300) NULL , PRIMARY KEY (JRN_SQ) , UNIQUE KEY UX_LAB_JOURNAL_MONTH (PRJ_SQ, YM) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='월간 연구일지';
CREATE TABLE IF NOT EXISTS TB_EEP_LAB_JOURNAL_H ( HIS_SQ int NOT NULL AUTO_INCREMENT , JRN_SQ int NOT NULL , ACTION_CD varchar(20) NOT NULL , STATUS_CD varchar(12) NOT NULL COMMENT '처리 후 상태' , ACTOR_ID varchar(50) NOT NULL , ACTOR_NM varchar(100) NULL , NOTE varchar(1000) NULL , REG_DT datetime NOT NULL COMMENT 'KST' , PRIMARY KEY (HIS_SQ) , KEY IX_LAB_HIS_JOURNAL (JRN_SQ) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='월간 연구일지 처리 이력';
CREATE TABLE IF NOT EXISTS TB_EEP_LAB_TEAM_M ( TEAM_SQ int NOT NULL AUTO_INCREMENT , TEAM_NM varchar(100) NOT NULL , FIELD_NM varchar(200) NULL COMMENT '연구 분야' , PLACE varchar(200) NULL COMMENT '소재지' , USE_YN char(1) NOT NULL DEFAULT 'Y' , MEMO varchar(1000) NULL , MANAGER_EMPLY_ID varchar(50) NULL COMMENT '안 씀: 결재라인은 TB_EEP_LAB_APPR_R' , CEO_EMPLY_ID varchar(50) NULL COMMENT '안 씀: 결재라인은 TB_EEP_LAB_APPR_R' , UPDT_EMPLY_ID varchar(50) NULL , UPDT_DT datetime NULL , PRIMARY KEY (TEAM_SQ) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='연구팀';
CREATE TABLE IF NOT EXISTS TB_EEP_LAB_SIGN_H ( SIGN_SQ int NOT NULL AUTO_INCREMENT , EMPLY_ID varchar(50) NOT NULL , SIGN_IMG mediumtext NOT NULL COMMENT 'PNG data URI' , REG_DT datetime NOT NULL COMMENT 'KST' , PRIMARY KEY (SIGN_SQ) , KEY IX_LAB_SIGN_EMPLY (EMPLY_ID) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='결재자 서명. 바꿔도 새 행을 쌓아 과거 승인의 서명을 남긴다';
CREATE TABLE IF NOT EXISTS TB_EEP_LAB_APPR_R ( TEAM_SQ int NOT NULL , STEP_NO int NOT NULL COMMENT '1부터 결재 순서' , STEP_NM varchar(50) NOT NULL COMMENT '부서장, 대표 같은 단계 이름' , EMPLY_ID varchar(50) NOT NULL COMMENT '결재자 계정' , PRIMARY KEY (TEAM_SQ, STEP_NO) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='연구팀 결재라인';
CREATE TABLE IF NOT EXISTS TB_EEP_LAB_JOURNAL_STEP ( JRN_SQ int NOT NULL , STEP_NO int NOT NULL , STEP_NM varchar(50) NOT NULL , EMPLY_ID varchar(50) NOT NULL , DONE_NM varchar(100) NULL COMMENT '확인한 사람 이름' , DONE_DT datetime NULL COMMENT 'KST' , SIGN_SQ int NULL , PRIMARY KEY (JRN_SQ, STEP_NO) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='일지 결재 단계. 제출할 때 결재라인을 복사해 이후 결재라인을 바꿔도 그대로 둔다';
ALTER TABLE TB_EEP_LAB_RESEARCHER_M ADD COLUMN IF NOT EXISTS TEAM_SQ int NULL AFTER RSCH_SQ; ALTER TABLE TB_EEP_LAB_PROJECT_M ADD COLUMN IF NOT EXISTS TEAM_SQ int NULL AFTER PRJ_SQ; ALTER TABLE TB_EEP_LAB_PROJECT_M MODIFY MANAGER_EMPLY_ID varchar(50) NULL, MODIFY CEO_EMPLY_ID varchar(50) NULL; ALTER TABLE TB_EEP_LAB_JOURNAL_H ADD COLUMN IF NOT EXISTS SIGN_SQ int NULL AFTER NOTE; ALTER TABLE TB_EEP_LAB_JOURNAL_M ADD COLUMN IF NOT EXISTS CUR_STEP int NULL COMMENT '결재 중인 단계' AFTER STATUS_CD; ALTER TABLE TB_EEP_LAB_JOURNAL_M ADD COLUMN IF NOT EXISTS MAIL_DT datetime NULL COMMENT '마감 메일 보낸 시각'; ALTER TABLE TB_EEP_LAB_JOURNAL_M ADD COLUMN IF NOT EXISTS ORIGIN_LINK varchar(500) NULL COMMENT '첨부파일 링크'; ALTER TABLE TB_EEP_LAB_JOURNAL_M ADD COLUMN IF NOT EXISTS ATTACH_NM varchar(300) NULL COMMENT '첨부파일 이름(확장자 포함)' AFTER ORIGIN_LINK;
UPDATE TB_EEP_LAB_JOURNAL_M J SET J.ATTACH_NM = (SELECT SUBSTRING_INDEX(H.NOTE, '옮김: ', -1) FROM TB_EEP_LAB_JOURNAL_H H WHERE H.JRN_SQ = J.JRN_SQ AND H.ACTION_CD = 'CREATE' AND H.NOTE LIKE '%옮김: %' ORDER BY H.HIS_SQ LIMIT 1) WHERE J.ATTACH_NM IS NULL AND J.ORIGIN_LINK IS NOT NULL;
INSERT INTO TB_EEP_LAB_TEAM_M (TEAM_NM, USE_YN, MANAGER_EMPLY_ID, CEO_EMPLY_ID, UPDT_DT) SELECT '기본 연구팀', 'Y', MAX(MANAGER_EMPLY_ID), MAX(CEO_EMPLY_ID), NOW() FROM TB_EEP_LAB_PROJECT_M WHERE NOT EXISTS (SELECT 1 FROM TB_EEP_LAB_TEAM_M) HAVING COUNT(*) > 0; UPDATE TB_EEP_LAB_RESEARCHER_M SET TEAM_SQ = (SELECT MIN(TEAM_SQ) FROM TB_EEP_LAB_TEAM_M) WHERE TEAM_SQ IS NULL; UPDATE TB_EEP_LAB_PROJECT_M SET TEAM_SQ = (SELECT MIN(TEAM_SQ) FROM TB_EEP_LAB_TEAM_M) WHERE TEAM_SQ IS NULL;
INSERT IGNORE INTO TB_EEP_LAB_APPR_R (TEAM_SQ, STEP_NO, STEP_NM, EMPLY_ID) SELECT TEAM_SQ, 1, '부서장', MANAGER_EMPLY_ID FROM TB_EEP_LAB_TEAM_M T WHERE MANAGER_EMPLY_ID IS NOT NULL AND NOT EXISTS (SELECT 1 FROM TB_EEP_LAB_APPR_R A WHERE A.TEAM_SQ = T.TEAM_SQ); INSERT IGNORE INTO TB_EEP_LAB_APPR_R (TEAM_SQ, STEP_NO, STEP_NM, EMPLY_ID) SELECT TEAM_SQ, 2, '대표', CEO_EMPLY_ID FROM TB_EEP_LAB_TEAM_M T WHERE CEO_EMPLY_ID IS NOT NULL AND NOT EXISTS (SELECT 1 FROM TB_EEP_LAB_APPR_R A WHERE A.TEAM_SQ = T.TEAM_SQ AND A.STEP_NO <> 1); UPDATE TB_EEP_LAB_TEAM_M SET MANAGER_EMPLY_ID = NULL, CEO_EMPLY_ID = NULL WHERE MANAGER_EMPLY_ID IS NOT NULL OR CEO_EMPLY_ID IS NOT NULL;

UPDATE TB_EEP_LAB_TEAM_M
SET TEAM_NM = #{TEAM_NM}, FIELD_NM = NULLIF(#{FIELD_NM}, ''), PLACE = NULLIF(#{PLACE}, ''), USE_YN = #{USE_YN}, UPDT_EMPLY_ID = #{UPDT_EMPLY_ID}, UPDT_DT = NOW()
WHERE TEAM_SQ = #{TEAM_SQ}

mapper.select:
SELECT COUNT(*) FROM TB_EEP_LAB_RESEARCHER_M
WHERE TEAM_SQ = #{TEAM_SQ} AND STAFF_SQ = #{STAFF_SQ} AND RSCH_SQ <> #{RSCH_SQ}
  AND START_DT <= IFNULL(NULLIF(#{END_DT}, ''), '9999-12-31')
  AND IFNULL(END_DT, '9999-12-31') >= #{START_DT}

mapper.update:
UPDATE TB_EEP_LAB_RESEARCHER_M
SET STAFF_SQ = #{STAFF_SQ}, ROLE_CD = #{ROLE_CD}, START_DT = #{START_DT}, END_DT = NULLIF(#{END_DT}, ''), UPDT_EMPLY_ID = #{UPDT_EMPLY_ID}, UPDT_DT = NOW()
WHERE RSCH_SQ = #{RSCH_SQ} AND TEAM_SQ = #{TEAM_SQ}

UPDATE TB_EEP_LAB_PROJECT_M
SET TEAM_SQ = #{TEAM_SQ}, PRJ_NM = #{PRJ_NM}, START_DT = #{START_DT}, END_DT = #{END_DT}, PLACE = #{PLACE}, DRIVE_FOLDER_ID = #{DRIVE_FOLDER_ID}, UPDT_EMPLY_ID = #{UPDT_EMPLY_ID}, UPDT_DT = NOW()
WHERE PRJ_SQ = #{PRJ_SQ}
